"""Personal identifiers left in AI logs, by category; prints counts and folders only, never values.

Usage: identity_check.py HOOK_DIR LOG_ROOT [--fix]
Identifiers are derived on this machine: the hook's identity (home, user and its variants, host, device
owner, git user and e-mail), e-mail local parts from the repository's commit history, and the private terms.
Matches are case-insensitive and also catch the forms paths use (dots or underscores for dashes).
With --fix, replaces matches in transcript.jsonl string values with the hook's markers and re-renders
transcript.md (header counts updated); only files that change are written.
"""
import json
import re
import subprocess
import sys
from collections import Counter, defaultdict
from pathlib import Path

sys.path.insert(0, sys.argv[1])
import transcript_privacy as tp  # noqa: E402
from save_transcript import render_markdown  # noqa: E402

sys.path.insert(0, str(Path(__file__).parent))
from render_check import header  # noqa: E402

REPO = Path("~/leveraged-etf-risk-analytics")
ROOT = Path(sys.argv[2])
FIX = "--fix" in sys.argv
red = tp.Redactor.for_project(REPO)
ident = tp.detect_identity(REPO)
terms, _ = tp.load_config(REPO)

values = defaultdict(set)
for cat, vals in ident.items():
    for v in vals:
        if v and len(v) >= 3:
            values[cat].add(v)
home = ident["home"][0]
values["home"].add(home.replace("/", "-"))  # the -Users-<name>- form in project slugs
user = ident["user"][0]
for part in re.split(r"[^A-Za-z0-9]+", user):
    if len(part) >= 4:
        values["user"].add(part)  # e.g. the name part of a dotted account name
emails = subprocess.run(["git", "-C", str(REPO), "log", "--all", "--format=%ae%n%ce"], capture_output=True, text=True).stdout.split()
for e in set(emails) | set(ident["git-email"]):
    if "@" in e and e.lower() not in tp.EMAIL_ALLOWLIST and not e.endswith("noreply.github.com"):
        values["git-email"].add(e)
        local = e.split("@")[0]
        if len(local) >= 4:
            values["email-local-part"].add(local)
for t in terms:
    if len(t) >= tp.MIN_LITERAL_CHARS:
        values["private-term"].add(t)


def variants(v):
    """The value as written, and with dashes, dots and underscores interchanged (path slugs)."""
    core = re.escape(v)
    return re.sub(r"\\[-._]|[-._]", "[-._]", core)


patterns = {cat: re.compile("|".join(sorted((variants(v) for v in vals), key=len, reverse=True)), re.IGNORECASE)
            for cat, vals in values.items()}
MARKERS = {"home": "~", "user": "[REDACTED:user]", "host": "[REDACTED:host]", "device-owner": "[REDACTED:device-owner]",
           "git-user": "[REDACTED:git-user]", "git-email": "[REDACTED:email]", "email-local-part": "[REDACTED:email]",
           "private-term": "[REDACTED:private-term]"}
ORDER = ["home", "git-email", "email-local-part", "host", "device-owner", "git-user", "private-term", "user"]
PATHLIKE = re.compile(r"[~/][^\s\"'`]*")


def strings(o):
    if isinstance(o, str):
        yield o
    elif isinstance(o, list):
        for v in o:
            yield from strings(v)
    elif isinstance(o, dict):
        for k, v in o.items():
            yield k
            yield from strings(v)


def fix(o, counts):
    if isinstance(o, str):
        for cat in ORDER:
            o, n = patterns[cat].subn(MARKERS[cat], o)
            if n:
                counts[cat] += n
        return o
    if isinstance(o, list):
        return [fix(v, counts) for v in o]
    if isinstance(o, dict):
        return {k: fix(v, counts) for k, v in o.items()}
    return o


found, in_paths, folders, changed = Counter(), Counter(), defaultdict(set), []
for d in sorted(p for p in ROOT.iterdir() if p.is_dir()):
    for name in ("transcript.jsonl", "transcript.md"):
        text = (d / name).read_bytes().decode("utf-8")
        for cat in ORDER:
            for m in patterns[cat].finditer(text):
                found[(name, cat)] += 1
                folders[cat].add(d.name)
                line_tokens = PATHLIKE.findall(text[max(0, m.start() - 80):m.end() + 80])
                if any(m.group(0).lower() in t.lower() for t in line_tokens):
                    in_paths[cat] += 1
    if FIX:
        raw = (d / "transcript.jsonl").read_bytes().decode("utf-8")
        md = (d / "transcript.md").read_bytes().decode("utf-8")
        lines, counts, out = raw.split("\n"), Counter(), []
        for line in lines:
            if not line.strip():
                out.append(line)
                continue
            rec = json.loads(line)
            new = fix(rec, counts)
            out.append(line if new == rec else json.dumps(new, ensure_ascii=False))
        new_raw = "\n".join(out)
        if new_raw != raw:
            session, number, sent, hc = header(md)
            assert render_markdown(raw, session, number, sent, hc) == md
            for cat, n in counts.items():
                hc["email" if cat in ("git-email", "email-local-part") else cat] += n
            (d / "transcript.jsonl").write_bytes(new_raw.encode("utf-8"))
            (d / "transcript.md").write_bytes(render_markdown(new_raw, session, number, sent, hc).encode("utf-8"))
            changed.append((d.name, dict(counts)))

print("identifier categories checked (distinct values): " + ", ".join(f"{c} {len(v)}" for c, v in sorted(values.items())))
total = sum(found.values())
print(f"matches: {total}")
for (name, cat), n in sorted(found.items()):
    print(f"  {name} | {cat}: {n} ({len(folders[cat])} folders; inside a path: {in_paths[cat]})")
for f, c in changed:
    print(f"  fixed {f}: {c}")

